var supported = ['en','de','es','fr','it'];
var picker = document.querySelector('#site-language');
var originalTitle = document.title;
var selected;
try { selected = localStorage.getItem('fjelia-language'); } catch (_) {}
var requested = new URL(location.href).searchParams.get('lang');
var browserLanguage = (navigator.language || 'en').split('-')[0].toLowerCase();
var current = supported.includes(requested) ? requested : supported.includes(selected) ? selected : supported.includes(browserLanguage) ? browserLanguage : 'en';
function text(key) { return copy[current][key] || copy.en[key] || key; }
function plain(html) { var temp = document.createElement('div'); temp.innerHTML = html; return temp.textContent; }
function updateLinks() {
  document.querySelectorAll('a[href]').forEach(function (link) {
    var href = link.getAttribute('href');
    if (!href || href[0] === '#') return;
    var url = new URL(href, location.href);
    if (url.origin !== location.origin || !(/\.html$/.test(url.pathname) || url.pathname.endsWith('/'))) return;
    url.searchParams.set('lang', current);
    link.setAttribute('href', url.pathname + url.search + url.hash);
  });
}
function apply(lang, remember) {
  if (!supported.includes(lang)) lang = 'en';
  current = lang;
  document.documentElement.lang = lang;
  document.querySelectorAll('[data-i18n]').forEach(function (el) {
    el.innerHTML = text(el.dataset.i18n);
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(function (el) {
    el.setAttribute('placeholder', text(el.dataset.i18nPlaceholder));
  });
  document.querySelectorAll('.language-picker').forEach(function (el) { el.hidden = false; });
  if (picker) { picker.value = lang; picker.setAttribute('aria-label',text('language')); }
  document.querySelectorAll('.video-index').forEach(function (el,i) { el.textContent = '0' + (i+1) + ' / ' + text('walkthrough'); });
  document.querySelectorAll('.screen-link,.weather-link,.plan-capture-link,.feature-capture').forEach(function (link) {
    var figure = link.closest('figure');
    var heading = figure.querySelector('h3');
    var description = figure.querySelector('figcaption p');
    link.dataset.caption = heading.textContent;
    link.setAttribute('aria-label',text('enlarge')+' '+heading.textContent);
    link.querySelector('img').alt = description.textContent;
  });
  document.querySelectorAll('.sport img').forEach(function (img) { var label=img.closest('figure').querySelector('figcaption'); if(label) img.alt=label.textContent; });
  document.querySelectorAll('.app-preview').forEach(function (video) { var article = video.closest('article'); video.setAttribute('aria-label', article ? article.querySelector('h3').textContent : text('demo_0_title')); });
  document.querySelectorAll('[data-i18n-alt]').forEach(function (el) { el.alt = plain(text(el.dataset.i18nAlt)); });
  var story = document.querySelector('.hero-story-nav'); if (story) story.setAttribute('aria-label', text('hero_story_label'));
  var walkthroughs = document.querySelector('.walkthrough-nav'); if (walkthroughs) walkthroughs.setAttribute('aria-label', text('gallery_label'));
  var planViews = document.querySelector('.plan-view-picker'); if (planViews) planViews.setAttribute('aria-label', text('plan_views_label'));
  var qr = document.querySelector('.hero-qr'); if (qr) qr.setAttribute('aria-label', text('qr_title'));
  var storyStage = document.querySelector('.story-stage'); if (storyStage) storyStage.setAttribute('aria-label', text('story_preview'));
  var storyNav = document.querySelector('.story-stage-nav'); if (storyNav) storyNav.setAttribute('aria-label', text('story_nav_label'));
  var thresholdViews = document.querySelector('.threshold-view-picker'); if (thresholdViews) thresholdViews.setAttribute('aria-label', text('threshold_views_label'));
  document.querySelectorAll('nav[aria-label]').forEach(function (el) { el.setAttribute('aria-label', text(el.closest('footer') ? 'footer' : 'main')); });
  document.querySelectorAll('.hero-phone img').forEach(function (el) { el.alt = plain(text(el.closest('.phone-ai') ? 'demo_0_title' : el.closest('.phone-plan') ? 't052' : el.closest('.phone-front') ? 't031' : 't039')); });
  var close = document.querySelector('.dialog-close');
  if (close) close.setAttribute('aria-label',text('close'));
  var badge = document.querySelector('.badges'); if (badge) badge.setAttribute('aria-label',text('highlights'));
  document.querySelectorAll('.chips').forEach(function (el) { el.setAttribute('aria-label',text('sources')); });
  if (originalTitle.indexOf('Privacy') === 0) document.title = text('t155') + ' — Fjelia';
  else if (originalTitle.indexOf('Page not found') === 0) document.title = text('t204') + ' — Fjelia';
  else document.title = 'Fjelia — ' + plain(text('t010').replace(/<br\s*\/?>/g,' '));
  var description = document.querySelector('meta[name="description"]');
  if (description) description.content = plain(text(originalTitle.indexOf('Privacy') === 0 ? 't157' : 't011'));
  var ogTitle=document.querySelector('meta[property="og:title"]'); if(ogTitle) ogTitle.content=document.title;
  var ogDescription=document.querySelector('meta[property="og:description"]'); if(ogDescription && description) ogDescription.content=description.content;
  updateLinks();
  if (remember) {
    try { localStorage.setItem('fjelia-language',lang); } catch (_) {}
    var url = new URL(location.href); url.searchParams.set('lang',lang);
    try { history.replaceState(null,'',url); } catch (_) {}
  }
  document.dispatchEvent(new CustomEvent('fjelia-language-change',{detail:{language:lang}}));
}
window.FjeliaI18n = { t: text, language: function () { return current; } };
if (picker) picker.addEventListener('change',function () { apply(picker.value,true); });
apply(current,false);

